<?php $cpModel=mp_category_tree_model();$cpOptions=$cpModel->options(get_current_store_id(),(int)($q_id??0));$cpCurrent=(int)($parent_id??0);$cpLabel='Top-level category';foreach($cpOptions as $option)if((int)$option->id===$cpCurrent)$cpLabel=$option->category_path; ?>
<div class="mp-form-group form-group" data-category-parent><label>Parent category (optional)</label><input type="hidden" name="parent_id" value="<?= $cpCurrent; ?>"><details class="category-parent-picker"><summary><?= htmlspecialchars($cpLabel); ?></summary><div class="category-parent-options" role="group" aria-label="Parent category"><button type="button" data-category-id="0">Top-level category</button><?php foreach($cpOptions as $option):if((int)$option->status!==1)continue; ?><button type="button" data-category-id="<?= (int)$option->id; ?>"><?= htmlspecialchars($option->category_path); ?></button><?php endforeach; ?></div></details><small>Choose a parent to create a subcategory. Existing products keep their category assignments.</small></div>
<style>.category-parent-picker{border:1px solid var(--mp-border,#dce3df);border-radius:6px;background:var(--mp-surface,#fff);font-size:13px}.category-parent-picker summary{cursor:pointer;padding:12px}.category-parent-options{max-height:260px;overflow-y:auto;border-top:1px solid var(--mp-border,#dce3df)}.category-parent-options button{display:block;text-align:left;width:100%;padding:12px;border:0;background:transparent;color:inherit;font:inherit;cursor:pointer}.category-parent-options button:hover,.category-parent-options button:focus{background:var(--mp-bg,#f0f5f2)}[data-category-parent] small{display:block;font-size:11px;margin-top:6px;color:var(--mp-muted,#66736c)}</style>
<script>document.querySelectorAll('[data-category-parent]').forEach(function(picker){picker.querySelectorAll('[data-category-id]').forEach(function(button){button.addEventListener('click',function(){picker.querySelector('input[name="parent_id"]').value=button.dataset.categoryId;picker.querySelector('summary').textContent=button.textContent;picker.querySelector('details').open=false;});});});</script>
